# settings

`node src/app.js [config.json]` starts the app with the settings in the file. A file that is not valid JSON stops it with `bad config: <message>` and exit 1.

Tests: `npm test`.
#!/usr/bin/env node
import { loadConfig } from './config.js';

const DEFAULTS = { port: 8080, greeting: 'hi' };
let config;
try {
  config = { ...DEFAULTS, ...loadConfig(process.argv[2] ?? 'config.json') };
} catch (error) {
  process.stderr.write(`bad config: ${error.message}\n`);
  process.exit(1);
}
process.stdout.write(`listening on ${config.port}\n`);
import { readFileSync } from 'node:fs';

/** The settings in a JSON file. */
export function loadConfig(path) {
  return JSON.parse(readFileSync(path, 'utf8'));
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadConfig } from '../src/config.js';

const file = (text) => {
  const f = join(mkdtempSync(join(tmpdir(), 'cfg-')), 'config.json');
  writeFileSync(f, text);
  return f;
};

test('reads a config', () => assert.deepEqual(loadConfig(file('{"port": 9000}')), { port: 9000 }));
test('bad JSON throws', () => assert.throws(() => loadConfig(file('{port: 9000')), SyntaxError));

input.command:
node --version; printf '{
  "port": 9000,
  greeting: "x"
}' > /tmp/bad.json; node src/app.js /tmp/bad.json; echo "exit $?"; node src/app.js /tmp/nope.json; echo "exit $?"; npm test 2>&1 | tail -5

expect:
With a file F containing `{
  "port": 9000,
  greeting: "x"
}`, `node src/app.js F` exits with status 1, writes nothing containing `listening` to stdout, and writes one stderr line that starts with `bad config:` and contains both the path F exactly as passed and the text `line 3 column 3`.

proofs.line:
With a file F containing `{
  "port": 9000,
  greeting: "x"
}`, `node src/app.js F` exits with status 1, writes nothing containing `listening` to stdout, and writes one stderr line that starts with `bad config:` and contains both the path F exactly as passed and the text `line 3 column 3`.

proofs.how:
d=$(mktemp -d); printf '{
  "port": 9000,
  greeting: "x"
}' > $d/config.json; node src/app.js $d/config.json >$d/out 2>$d/err; echo "exit $?"; cat $d/out; cat $d/err  — expect exit 1, empty stdout (no 'listening'), and a stderr line starting 'bad config:' that contains $d/config.json and 'line 3 column 3'.

d=$(mktemp -d); printf '{
  "port": 9000,
  greeting: "x"
}' > $d/config.json; node --input-type=module -e "import {loadConfig} from './src/config.js'; try { const r = loadConfig(process.argv[1]); console.log('RETURNED', JSON.stringify(r)); process.exit(2); } catch (e) { console.log(e.message.includes(process.argv[1]) ? 'OK' : 'NO PATH: ' + e.message); }" $d/config.json  — expect 'OK'.
